<?php require_once "../config/auth.php";requireAdmin();require_once "../config/database.php";$id=(int)($_GET['id']??0);if(!$id)exit('Invalid club.');
if($_SERVER['REQUEST_METHOD']==='POST'){$n=trim($_POST['club_name']);$d=trim($_POST['description']);$co=trim($_POST['coordinator']);$cat=(int)$_POST['category_id'];$s=$conn->prepare('UPDATE clubs SET club_name=?,category_id=?,description=?,coordinator=? WHERE club_id=?');$s->bind_param('sissi',$n,$cat,$d,$co,$id);$s->execute();header('Location: manage-clubs.php');exit;}
$s=$conn->prepare('SELECT * FROM clubs WHERE club_id=?');$s->bind_param('i',$id);$s->execute();$c=$s->get_result()->fetch_assoc();$cats=$conn->query('SELECT * FROM categories ORDER BY category_name');?>
<!doctype html><html><head><title>Edit Club</title><link rel="stylesheet" href="../css/style.css"></head><body><div class="form-wrap"><div class="form-box"><h2>Edit Club</h2><form method="post"><label>Club Name</label><input name="club_name" value="<?=htmlspecialchars($c['club_name'])?>" required><label>Category</label><select name="category_id"><?php while($cat=$cats->fetch_assoc()):?><option value="<?=$cat['category_id']?>" <?=$cat['category_id']==$c['category_id']?'selected':''?>><?=htmlspecialchars($cat['category_name'])?></option><?php endwhile;?></select><label>Description</label><textarea name="description" rows="4"><?=htmlspecialchars($c['description'])?></textarea><label>Coordinator</label><input name="coordinator" value="<?=htmlspecialchars($c['coordinator'])?>" required><br><br><button class="btn full">Update Club</button></form></div></div></body></html>
